// Service worker: keeps the whole app and every question bank on the device, so Study Practice
// opens and works with no internet after the first visit. Nothing is fetched from other sites.
// GENERATED by tools/build_content.py from tools/sw.template.js: edit the template, not sw.js.

const VERSION = '__VERSION__';
const PREFIX = 'study-practice-';
const DEV = ['localhost', '127.0.0.1', '[::1]'].includes(self.location.hostname);
const FILES = __FILES__;

// Look only in this app's own cache. Other apps on the same site address (ec-drives.github.io
// also serves drive-timer) keep their own caches, and their files are never served from here.
function fromCache(req) {
  return caches.open(VERSION).then((c) => c.match(req, { ignoreSearch: true }));
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(VERSION)
      .then((cache) => cache.addAll(FILES.map((p) => new Request(p, { cache: 'reload' }))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith(PREFIX) && k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // the app never calls other sites
  const scope = new URL(self.registration.scope);
  const rel = url.pathname.startsWith(scope.pathname) ? url.pathname.slice(scope.pathname.length) : url.pathname;
  if (rel.startsWith('test/') || rel.startsWith('tools/')) return; // development files
  if (DEV) {
    // on the laptop: newest files first, the cache only when offline
    event.respondWith(fetch(req).catch(() => fromCache(req).then((hit) => hit || Response.error())));
    return;
  }
  event.respondWith(
    fromCache(req).then((hit) => {
      if (hit) return hit;
      return fetch(req).then((res) => {
        if (res.ok && res.type === 'basic') {
          const copy = res.clone();
          caches.open(VERSION).then((c) => c.put(req, copy));
        }
        return res;
      }).catch(() => (req.mode === 'navigate' ? fromCache('index.html') : Response.error()));
    }),
  );
});
